 IEnumerator Guard(IEnumerator root){var stack=new Stack<IEnumerator>();stack.Push(root);while(stack.Count>0){var top=stack.Peek();bool more=false;object step=null;try{more=top.MoveNext();if(more)step=top.Current;}catch(Exception e){Check(false,"EXCEPTION "+e);break;}if(!more){stack.Pop();continue;}if(step is IEnumerator nested)stack.Push(nested);else yield return step;}Finish();}
 void Finish(){Input();Status="DONE checks="+checks.Count+" failures="+checks.Count(x=>x.StartsWith("FAIL"));File.WriteAllText(folder+"/status.txt",Status);File.WriteAllLines(folder+"/results.txt",checks);Cleanup();Debug.Log(Status);}
 void Cleanup(){if(cleaning)return;cleaning=true;P04EvidenceRecorder.Stop();if(saves&&oldStore!=null)typeof(GameSaveService).GetProperty("Store").GetSetMethod(true).Invoke(saves,new object[]{oldStore});if(ReferenceEquals(GameplayInput.Replay,this))GameplayInput.Replay=null;}
 void OnDestroy(){Cleanup();}
 void Check(bool pass,string s){checks.Add((pass?"PASS ":"FAIL ")+s);File.WriteAllLines(folder+"/results.txt",checks);}
