 IEnumerator Directions(Scene03MazeController m){var start=(Vector2)Player.transform.position;var combos=new[]{new[]{KeyCode.W},new[]{KeyCode.S},new[]{KeyCode.A},new[]{KeyCode.D},new[]{KeyCode.W,KeyCode.A},new[]{KeyCode.W,KeyCode.D},new[]{KeyCode.S,KeyCode.A},new[]{KeyCode.S,KeyCode.D}};var names=new[]{"up","down","left","right","up_left","up_right","down_left","down_right"};for(int i=0;i<combos.Length;i++){Label("M29 direction "+names[i]);Vector2 from=Player.transform.position;Input(combos[i]);yield return Wait(.20f);Vector2 delta=(Vector2)Player.transform.position-from;var art=Player.GetComponent<P02ActorPresentation>();Check(delta.magnitude>.12f&&(!art||art.Direction==names[i]),"M29 real movement and accepted pose "+names[i]+" delta="+delta+" pose="+(art?art.Direction:"existing actor adapter"));yield return Shot("15A_Direction_"+names[i]);Input(combos[i].Select(k=>k==KeyCode.W?KeyCode.S:k==KeyCode.S?KeyCode.W:k==KeyCode.A?KeyCode.D:KeyCode.A).ToArray());yield return Wait(.20f);Input();yield return Wait(.08f);}Check(!m.WouldOverlap(m.CurrentLayout,Player.transform.position,Player.GetComponent<Collider2D>().bounds.extents),"eight direction movement stays in real maze geometry");}
 IEnumerator WalkMaze(Scene03MazeController m){var start=m.CellAt(Player.transform.position);var queue=new Queue<(Vector2Int,int)>();var prev=new Dictionary<(Vector2Int,int),(Vector2Int,int)>();var root=(start,m.CurrentLayout);queue.Enqueue(root);prev[root]=root;(Vector2Int,int) goal=root;bool found=false;var dirs=new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right};while(queue.Count>0){var cur=queue.Dequeue();if(cur.Item1==new Vector2Int(0,19)){goal=cur;found=true;break;}foreach(var dir in dirs){var n=cur.Item1+dir;var key=(n,cur.Item2);if(m.layouts[cur.Item2].CanStep(cur.Item1,n)&&!prev.ContainsKey(key)){prev[key]=cur;queue.Enqueue(key);}}var sw=(cur.Item1,1-cur.Item2);if(!prev.ContainsKey(sw)){prev[sw]=cur;queue.Enqueue(sw);}}Need(found,"two-layout route exists");var path=new List<(Vector2Int,int)>();for(var a=goal;a!=root;a=prev[a])path.Add(a);path.Reverse();int step=0;foreach(var n in path){Label("maze route "+(++step)+"/"+path.Count+" cell="+n.Item1+" layout="+n.Item2);if(n.Item2!=m.CurrentLayout){yield return Pulse(KeyCode.Q);yield return Wait(.7f);yield return Pulse(KeyCode.Space);yield return Until(()=>!Rt.GetComponent<CameraModeController>().IsBusy&&!Rt.GetComponent<CameraModeController>().IsRaised);}else{var target=m.CellCenter(n.Item1);float elapsed=0;while(m.IsInMaze&&Vector2.Distance(Player.transform.position,target)>.08f&&elapsed<5){var delta=target-(Vector2)Player.transform.position;var keys=new List<KeyCode>();if(Mathf.Abs(delta.x)>.04f)keys.Add(delta.x>0?KeyCode.D:KeyCode.A);if(Mathf.Abs(delta.y)>.04f)keys.Add(delta.y>0?KeyCode.W:KeyCode.S);Input(keys.ToArray());yield return Wait(.025f);elapsed+=.025f;}Input();if(m.IsInMaze)Need(Vector2.Distance(Player.transform.position,target)<.15f,"native movement reached "+n.Item1);}}yield return Until(()=>m.IsAtRiver,12);}
 IEnumerator Rhythm(GuitarRhythmGame r){Label("four rhythm phrases with retry and pause");bool pauseDone=false;int judgedCount=0;r.Judged+=(k,ok,t,grade)=>{File.AppendAllText(folder+"/rhythm_judgments.csv",r.PhraseIndex+","+r.RetryCount+","+k+","+ok+","+t.ToString("F3")+","+grade+"\n");if(ok)judgedCount++;};int previous=-1,retry=-1,hit=-1;float last=0;bool shot=false;double end=Time.realtimeSinceStartup+190;while(r.IsRunning&&Time.realtimeSinceStartup<end){yield return Foreground();if(r.PhraseIndex>=r.phrases.Length){Input();yield return null;continue;}var p=r.phrases[Mathf.Clamp(r.PhraseIndex,0,3)];float t=r.PhraseTime;if(previous!=r.PhraseIndex||retry!=r.RetryCount||t<last-.5f){previous=r.PhraseIndex;retry=r.RetryCount;hit=-1;shot=false;File.AppendAllText(folder+"/rhythm_timing.csv","phrase="+previous+" first="+p.notes[0].time+" chordVisible="+(p.notes[0].time-r.ChordApproachSeconds)+" leftVisible="+(p.notes[0].time-r.approachSeconds)+" spaceVisible="+(p.notes[p.notes.Length-1].time-r.SpaceLeadSeconds)+"\n");}last=t;var keys=new List<KeyCode>{p.heldChord};bool deliberatelyMiss=previous==1&&retry==0;for(int i=0;i<p.notes.Length;i++)if(i>hit&&t>=p.notes[i].time-.02f){hit=i;if(!deliberatelyMiss||i!=0)keys.Add(p.notes[i].key);break;}Input(keys.ToArray());if(!pauseDone&&previous==0&&t>-.8f){Input(p.heldChord);var gp=Rt.GetComponent<GamePause>();gp.SetPaused(true);float frozen=r.PhraseTime;yield return new WaitForSecondsRealtime(.65f);Check(Mathf.Abs(r.PhraseTime-frozen)<.01f,"M31 pause preserves exact rhythm time");gp.SetPaused(false);pauseDone=true;}if(!shot&&previous==0&&t>0){shot=true;P04EvidenceRecorder.Begin(this,"18B_GuitarMotion",6);yield return Shot("18B_GuitarPlaying");}yield return null;}Input();Check(r.Completed&&r.RetryCount==1&&judgedCount>=r.phrases.Sum(p=>p.notes.Length),"four phrase hit timestamps and retry semantics");Check(!saves.CanSave(out _),"song cutscene still prohibits save");}
